from 写入第二遍 import add
add('18_002',1.5,'16:9，侧面眼部特写，青的眼睛、鼻根和刘海占画面右半，左半留出尘雾所在方向；固定构图。','青的眼睛沿画外尘缘向左扫过，眼皮没有松下来；一滴汗停在脸侧，她把眼睛停在先前最浓的那片烟尘，头部只跟上一点，嘴在画外没有发声。','画面左侧为浅米灰雾层形成的虚化背景，深浅缓慢交替。','上方云天冷白柔光，眼睛亮点较小，额侧保持柔暗。','近处一次压住的呼气，尘中两粒碎石落地声拉开间距。',phase='reaction',node={'青.阶段':'侧目搜寻尘中动静'},card={'opening':'她仍不相信对手已倒下。','beats':['扫过尘缘','停在浓尘处，头只跟一点'],'coupling':'看不到目标引出下一次试探。','landing':'注意固定在尘雾侧。'})
add('18_003',5.5,'16:9，青居中正面头肩近景，抬到脸侧的一只手留在右侧，额头到胸上入画；镜头由胸上缓推，落幅仍保留完整抬手与嘴角。','青先张开嘴试探一句，等不到回应，嘴角便故意撑成带笑的弯形；她把右手拢到脸侧，胸肩向尘雾方向探近，双眼睁大装得轻松。后句说到句尾，笑角略歪，眉毛抬起，她把拢着的手停住听动静，汗仍挂在脸侧。','浅米灰尘层与冷灰天空虚化成上下两层，近处背景安静。','上方云天冷白漫射，尘层反射少量中性光。','一次轻短吸气，护件与发束摩擦，周围碎屑落地声逐渐稀疏。',ja=['もう…','もうダメなの？坊や…？！'],tone='前句试探；后句强作轻松地逗弄，句尾上扬后停住等回应。',kind='mixed',phase='state',node={'青.阶段':'出声试探尘中武士'},card={'opening':'警惕仍在，她选择用嘴上挑衅探虚实。','beats':['开口等一拍','拢手前探，故意笑着挑衅','句尾停手，重新听尘中动静'],'coupling':'并没有听到回答，注意被下一镜突来的动静打断。','landing':'手还在脸侧，随时能转入防御。'})
add('19_001',1,'16:9，残墙上沿在画面下方近景，左侧尘团与右侧铅蓝云天同框；镜头沿尘中尖长通道向右甩摇，落幅停在通道尖端掠出画面右缘的位置。','浓尘左侧突然被高速身影穿破，一道窄而尖的空隙向右延长；尘缘先向通道两侧掀开，再从后方卷回，最前端的浅色尖痕掠出画面，残墙上落灰向同一方向抖开。','下方深灰残墙／屋顶轮廓、米灰尘团和后方铅蓝云天；浅色通道是烟尘被推开的空隙。','上方云天冷白漫射，尘雾被吹薄处显得更亮。','一记突然拔高的破风，尘土被掀开的刷响，残墙上细灰齐落。',phase='process',node={'武士.阶段':'冲出尘雾高速跃近'},meaning='环境通道先到，再在下一格揭晓武士已跃至青上方；白形不是实体光束。')
